const items = $input.all();
const response = items[0]?.json?.QueryResponse || {};
const invoices = response.Invoice || [];

let totalAmount = 0;
let paidCount = 0;
let unpaidCount = 0;

const rows = invoices.map(inv => {
  const amount = parseFloat(inv.TotalAmt || 0);
  totalAmount += amount;
  const isPaid = inv.Balance === 0;
  if (isPaid) paidCount++;
  else unpaidCount++;

  return {
    json: {
      invoiceId: inv.Id || '',
      invoiceNumber: inv.DocNumber || '',
      customerName: inv.CustomerRef?.name || '',
      amount: amount,
      currency: inv.CurrencyRef?.value || 'USD',
      balance: inv.Balance || 0,
      status: isPaid ? 'Paid' : 'Unpaid',
      dueDate: inv.DueDate || '',
      txnDate: inv.TxnDate || '',
      lastUpdated: inv.MetaData?.LastUpdatedTime || '',
      syncDate: new Date().toISOString()
    }
  };
});

if (rows.length === 0) {
  rows.push({
    json: {
      invoiceId: 'none',
      summary: 'No invoices found for this period',
      syncDate: new Date().toISOString()
    }
  });
}

return rows;

